-- Marca do escritório (logo + cores) no link e no PDF da proposta revisional.
-- 1) cria o campo; 2) configura a Aprove Consultoria com a logo e as cores dela.
alter table public.revisional_config add column if not exists marca jsonb not null default '{}'::jsonb;

insert into public.revisional_config (workspace_id, empresa_nome, marca)
values ('aproveconsultoria', 'Aprove Consultoria',
  jsonb_build_object('cor', '#550007', 'cor2', '#E1BB57', 'logo', 'data:image/jpeg;base64,'))
on conflict (workspace_id) do update set
  marca = excluded.marca,
  empresa_nome = case when coalesce(revisional_config.empresa_nome, '') = '' then excluded.empresa_nome else revisional_config.empresa_nome end,
  updated_at = now();
